/** Checks field names and nesting against the engine type, then narrows to it. */
function fixture<T>(json: LooseJson<EngineRun<T>>): EngineRun<T> {
  return json as EngineRun<T>;
}

/** The data of a run that succeeded. Throws at start-up if a fixture changed meaning. */
function data<T>(run: EngineRun<T>, name: string): T {
  if (run.data === null) throw new Error(`fixture ${name} has no data`);
  return run.data;
}

